import { useEffect, useState, type RefObject } from 'react'

export type ScrollFadeClass = '' | 'scroll-fade-top' | 'scroll-fade-bottom' | 'scroll-fade-both'

/**
 * Vertical counterpart of `useTabBarFade`: tracks whether the given scroll
 * container has overflow content above, below, both, or neither, and returns
 * the CSS mask class to apply (`scroll-fade-top` / `scroll-fade-bottom` /
 * `scroll-fade-both` from the DS utilities). Apply the class to the scroll
 * container itself -- the overflowing edge fades out, and once scrolled with
 * content on both sides, both edges fade.
 *
 * Listens to scroll on the container, plus resize (window + ResizeObserver on
 * the container and its children) and child add/remove, so the class updates
 * when the container size or its content changes.
 *
 * `changeKey` is an optional value that, when it changes, forces the effect to
 * re-run. Use this when the scroll container is conditionally rendered or only
 * becomes scrollable on a state change (e.g. an expandable grid): pass that
 * state so the hook re-attaches once the ref points at the scrollable element.
 */
export function useScrollFade(ref: RefObject<HTMLElement | null>, changeKey?: unknown): ScrollFadeClass {
  const [fade, setFade] = useState<ScrollFadeClass>('')

  useEffect(() => {
    const el = ref.current
    if (!el) return

    const update = () => {
      const { scrollTop, scrollHeight, clientHeight } = el
      // 1px tolerance handles sub-pixel rendering at the extreme edges.
      const canUp = scrollTop > 1
      const canDown = scrollTop < scrollHeight - clientHeight - 1
      const cls: ScrollFadeClass =
        canUp && canDown ? 'scroll-fade-both'
          : canUp ? 'scroll-fade-top'
          : canDown ? 'scroll-fade-bottom'
          : ''
      setFade(prev => prev === cls ? prev : cls)
    }

    update()
    el.addEventListener('scroll', update, { passive: true })
    const ro = new ResizeObserver(update)
    ro.observe(el)
    // Also observe each child -- a scrollable container's own size doesn't
    // change when overflow children are added, but ResizeObserver on the
    // children catches their sizing (e.g., async-loaded rows).
    Array.from(el.children).forEach(child => ro.observe(child))
    // MutationObserver catches add/remove of rows (e.g., when the data
    // snapshot arrives and renders the list).
    const mo = new MutationObserver(() => {
      Array.from(el.children).forEach(child => ro.observe(child))
      update()
    })
    mo.observe(el, { childList: true })
    window.addEventListener('resize', update)

    return () => {
      el.removeEventListener('scroll', update)
      ro.disconnect()
      mo.disconnect()
      window.removeEventListener('resize', update)
    }
  }, [ref, changeKey])

  return fade
}
